import ctypes, numpy as np
from scipy.interpolate import CubicSpline,PchipInterpolator
from scipy.ndimage import map_coordinates,distance_transform_edt,label
from scipy.optimize import minimize,differential_evolution
from PIL import Image
from design import CENTERS,dense_centers,S
lib=ctypes.CDLL('/app/output/brush_render.so');lib.raster.argtypes=[ctypes.c_void_p,ctypes.c_int,ctypes.c_void_p,ctypes.c_double,ctypes.c_double,ctypes.c_double,ctypes.c_int,ctypes.c_int,ctypes.c_void_p]
PAR=np.load('/app/output/brush_fit.npy')
T=np.array(Image.open('/app/target.png'))[:,:,0]<90
V,U=np.mgrid[:1024,:1024];labels,_=label(T)
MASKS=[labels==1, (labels==2)&((U<526)|((V<415)&(U<545))|((V>700)&(U<535))),labels==3,(labels==2)&(U>=525)&(V<502),(labels==2)&(U>=521)&(V>=472)&~((U>545)&(V<500))]

def initial(nodes):
 c=np.array(nodes,float);d=(2*c[:,2]*S+.55)/1.16
 grad=np.gradient(c[:,:2],axis=0);grad/=np.linalg.norm(grad,axis=1)[:,None]
 xy=c[:,:2]*S+grad*d[:,None]*1.50
 return np.column_stack([xy,d])

def path_from_nodes(nodes,step=.22):
 a=np.array(nodes);ds=np.linalg.norm(np.diff(a[:,:2],axis=0),axis=1);s=np.r_[0,np.cumsum(np.maximum(ds,.4))]
 ss=np.linspace(0,s[-1],int(s[-1]/step)+1)
 xy=CubicSpline(s,a[:,:2],bc_type='natural')(ss);d=PchipInterpolator(s,a[:,2])(ss)
 path=np.column_stack([xy,d])
 # Controlled vertical press and lift at fixed endpoints.
 pre=np.column_stack([np.tile(a[0,:2],(15,1)),np.linspace(-.5,a[0,2],15)])
 post=np.column_stack([np.tile(a[-1,:2],(25,1)),np.linspace(a[-1,2],-.5,25)])
 return np.vstack([pre,path,post])

def render(p,rect,scale=3):
 x0,y0,x1,y1=rect;W=int(np.ceil((x1-x0)*scale));H=int(np.ceil((y1-y0)*scale));m=np.zeros((H,W),np.uint8);p=np.ascontiguousarray(p,dtype=float)
 lib.raster(p.ctypes.data,len(p),PAR.ctypes.data,x0,y0,scale,W,H,m.ctypes.data)
 return m.astype(bool)

def setup(k,scale=3):
 vv,uu=np.where(MASKS[k]);rect=np.array([uu.min()-70,vv.min()-70,uu.max()+70,vv.max()+70])*S
 x0,y0,x1,y1=rect;Y,X=np.mgrid[:int(np.ceil((y1-y0)*scale)),:int(np.ceil((x1-x0)*scale))]
 t=map_coordinates(MASKS[k].astype(float),[((Y+.5)/scale+y0)/S,((X+.5)/scale+x0)/S],order=1,mode='constant')>.5
 signed=(distance_transform_edt(~t)-distance_transform_edt(t))/scale
 return rect,t,signed

def optimize(k,rounds=3):
 rect,t,sd=setup(k,3);a=initial(CENTERS[k]);np.save(f'/app/output/nodes{k}_initial.npy',a)
 def cost(vec):
  a=vec.reshape(-1,3);p=path_from_nodes(a)
  m=render(p,rect)
  false=m&~t;miss=t&~m
  # Ink outside > 1 mm penalized, and broad coverage encouraged.
  loss=(np.sum(false*(1+np.maximum(sd,0)*1.8))+np.sum(miss*1.0))/t.sum()
  # Keep knot sequence smooth, along the intended length.
  return loss
 b=[]
 for i,row in enumerate(a):
  rad=8 if k else 7
  b.extend([(row[0]-rad,row[0]+rad),(row[1]-rad,row[1]+rad),(.5,min(15,row[2]+6))])
 x=a.ravel();print(k,'initial',cost(x),flush=True)
 for j in range(rounds):
  res=minimize(cost,x,method='Powell',bounds=b,options={'maxiter':20,'xtol':.04,'ftol':.00015})
  if res.fun<cost(x):x=res.x
  print(k,j,cost(x),res.nfev,flush=True)
  np.save(f'/app/output/nodes{k}.npy',x.reshape(-1,3));show(k,x.reshape(-1,3))
 return x.reshape(-1,3)

def show(k,a):
 rect,t,sd=setup(k,4.506);m=render(path_from_nodes(a),rect,4.506)
 im=np.full((*t.shape,3),245,np.uint8);im[t]=[70,70,70];im[m]=[220,50,50];im[m&t]=[20,20,20]
 Image.fromarray(im).save(f'/app/output/optimized{k}.png')
 print('iou',(m&t).sum()/(m|t).sum(),'coverage',(m&t).sum()/t.sum(),'stray1mm',np.sum(m&(sd>1))/t.sum(),flush=True)
if __name__=='__main__':
 import sys
 for k in map(int,sys.argv[1:]):optimize(k)
